use axum::response::{IntoResponse, Response};
use axum::Json;
use serde::Serialize;

#[derive(Serialize, Clone, Debug, PartialEq)]
struct FieldError {
    name: String,
    why: String,
}

#[derive(Debug)]
enum AppError {
    NotFound,
    Conflict(String),
    Invalid(Vec<FieldError>),
    Unauthorized,
    Internal(String),
}

impl AppError {
    fn status(&self) -> StatusCode {
        match self {
            AppError::NotFound => StatusCode::NOT_FOUND,
            AppError::Conflict(_) => StatusCode::CONFLICT,
            AppError::Invalid(_) => StatusCode::UNPROCESSABLE_ENTITY,
            AppError::Unauthorized => StatusCode::UNAUTHORIZED,
            AppError::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
    fn code(&self) -> &'static str {
        match self {
            AppError::NotFound => "not_found",
            AppError::Conflict(_) => "conflict",
            AppError::Invalid(_) => "invalid",
            AppError::Unauthorized => "unauthorized",
            AppError::Internal(_) => "internal",
        }
    }
}

use axum::extract::Path;
use axum::routing::get;

async fn boom(Path(kind): Path<String>) -> Result<&'static str, AppError> {
    Err(match kind.as_str() {
        "nf" => AppError::NotFound,
        "conflict" => AppError::Conflict("name taken".into()),
        "invalid" => AppError::Invalid(vec![FieldError { name: "name".into(), why: "short".into() }]),
        "auth" => AppError::Unauthorized,
        _ => AppError::Internal("sql: boom at db.rs:12".into()),
    })
}

fn app() -> Router {
    Router::new().route("/e/{kind}", get(boom))
}

#[tokio::main]
async fn main() {
    let app = app();
    for k in ["nf", "conflict", "invalid", "auth", "boom"] {
        let (s, b) = call(&app, "GET", &format!("/e/{k}"), "").await;
        println!("{} {b}", s.as_u16());
    }
}

